function lidWide(){const id=CUR.data||CUR.id;if(LIDWC[id]!==undefined)return LIDWC[id];if(typeof LIDW==='undefined'||!LIDW[id])return LIDWC[id]=null;
  const[x0,y0,st,nx,ny,z0,b64]=LIDW[id];return LIDWC[id]={x0,y0,st,nx,ny,d:lidDecode(b64,nx,ny,z0,100)};}
// course-frame ground: {z, w} with w easing from 0 to 1 over the outer 25 yards of the lidar coverage
/* lidar ground over driving ranges outside the course grid (Oct 2026, pipeline/ranges): per course [x0,y0,st,nx,ny,z0,b64], course yards like LIDW */
const RLID={"caledonia":[198,628,3.0,129,164,2.92,""],"judge":[-860,-338,3.0,142,148,84.126,""],"sandvalley":[3387,-1433,3.0,113,90,332.849,""],"heritage":[1529,-593,3.0,129,164,2.92,""],"lehman":[-1640,68,3.0,108,141,404.606,""],"mammoth":[3387,-1433,3.0,113,90,332.849,""],"lido":[3387,-1433,3.0,113,90,332.849,""],"sedge":[3387,-1433,3.0,113,90,332.849,""]},RLIDC={};
function rlidW(X,Y){const id=CUR&&CUR.id;if(!id||!RLID[id])return null;const L=RLIDC[id]||(RLIDC[id]=(([x0,y0,st,nx,ny,z0,b64])=>({x0,y0,st,nx,ny,d:lidDecode(b64,nx,ny,z0,100)}))(RLID[id]));
  const fx=(X-L.x0)/L.st,fy=(Y-L.y0)/L.st;if(fx<1||fy<1||fx>L.nx-2.01||fy>L.ny-2.01)return null;const e=Math.min(fx-1,L.nx-2.01-fx,fy-1,L.ny-2.01-fy)*L.st;return{z:lidCubic(L.d,L.nx,L.ny,fx,fy),w:smooth(0,20,e)};}
